from pathlib import Path
import subprocess,json,statistics,resource,fcntl,hashlib
p=Path(__file__).parent;fixtures=json.loads((p/'verification.json').read_text())['fixtures'];names=['example_00.in','all_same_00.in','small_random_00.in','max_random_00.in','max_random_01.in','max_colinear_00.in','near_circle_00.in','max_ans_00.in'];fixtures=[f for f in fixtures if f['name']in names];sha=lambda b:hashlib.sha256(b).hexdigest();d={'status':'INCOMPLETE','measurements':{}}
with open('/tmp/sirkit_performance_cpu14.lock','a')as a,open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a')as b:
 fcntl.flock(a,fcntl.LOCK_EX);fcntl.flock(b,fcntl.LOCK_EX)
 for mode in ['gcc_skip','gcc_native','clang_skip']:
  d['measurements'][mode]={}
  for f in fixtures:
   raw={'full':[],'split':[]}
   for rep in range(7):
    for form in (['full','split']if rep%2==0 else['split','full']):
     with open(f['input'],'rb')as inp:
      before=resource.getrusage(resource.RUSAGE_CHILDREN);q=subprocess.run(['taskset','-c','14',str(p/(mode+'_'+form))],stdin=inp,capture_output=True);after=resource.getrusage(resource.RUSAGE_CHILDREN)
     assert q.returncode==0 and not q.stderr and sha(q.stdout)==f['output_sha256'];raw[form].append(1000*(after.ru_utime+after.ru_stime-before.ru_utime-before.ru_stime))
   med={form:statistics.median(v)for form,v in raw.items()};d['measurements'][mode][f['name']]={'raw_cpu_ms':raw,'medians_cpu_ms':med};print(mode,f['name'],{k:round(v,3)for k,v in med.items()},flush=True)
d['status']='PASS';(p/'performance.json').write_text(json.dumps(d,indent=2)+'\n')

